'use strict';
let projectChild='mat';
function renderJuniorProjects(){
 const f=DATA.project_focus,root=document.querySelector('#junior-projects');if(!f||!root)return;
 const labels={age_fit:"Es muy adecuado para su edad.",confirm:"el permiso para especificar",excluded:"No es adecuado ahora."},names={mat:"Matvey · 9",osc:"Oscar · 6"};
 root.innerHTML=`<div class="project-heading"><div><p class="section-kicker">PROYECTOS PARA LOS MÁS PEQUEÑOS · ${esc(f.checked)}</p><h3>aplicaciones. juegos. código espacial.</h3><p>${esc(f.conclusion)}</p></div><div class="project-child" role="group" aria-label="niño para el recorrido de proyecto">${Object.entries(names).map(([id,name])=>`<button data-project-child="${id}" aria-pressed="${id===projectChild}" class="${id===projectChild?'active':''}">${name}</button>`).join('')}</div></div><div class="project-grid">${f.routes.map((r,i)=>`<article class="project-card" data-project-route="${esc(r.id)}"><div class="project-card-top"><span class="project-number">0${i+1}</span><span class="project-fit ${esc(r.fit[projectChild])}">${esc(labels[r.fit[projectChild]])}</span></div><h4>${esc(r.name)}</h4><p class="project-status">${esc(r.status)}</p><p>${esc(r.detail)}</p><p class="project-gate">${esc(names[projectChild])}: ${esc(r.fit_note[projectChild])}</p><p><b>el siguiente paso:</b> ${esc(r.next)}</p><div class="project-links">${r.ids.map(id=>`<button class="league-link" data-open="${esc(id)}">${esc(id)} · ${esc(EVENTS.find(e=>e.id===id)?.title||id)} →</button>`).join('')}${r.league?`<button class="league-link" data-project-profile="${esc(r.league)}">todos los requisitos del programa</button>`:''}<a href="${esc(r.source)}" target="_blank" rel="noopener">Fuente oficial ↗</a></div></article>`).join('')}</div><details class="project-gaps"><summary>condiciones y límites no resueltos de la investigación</summary><ul>${f.gaps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><div class="project-downloads"><a href="downloads/STEM_junior_projects.md" download>rutas y condiciones · Markdown ↓</a><a href="downloads/STEM_junior_projects.json" download>datos de los trayectos · JSON ↓</a></div>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.projectChild){projectChild=b.dataset.projectChild;renderJuniorProjects();document.querySelector(`[data-project-child="${projectChild}"]`).focus({preventScroll:true})}
 if(b.dataset.projectProfile){leagueState.tab='guide';leagueState.query='';leagueState.group='';leagueState.age='';leagueState.opened.add(b.dataset.projectProfile);renderLeagueGuide();const x=document.getElementById('league-'+b.dataset.projectProfile);x.scrollIntoView({behavior:'smooth',block:'start'});x.querySelector('summary').focus({preventScroll:true})}
});
